// THE APP ICON (MC-14, 2026-09-11): the wall's deep slate with the pale play
// glyph the bands wear, as PNG bytes — what a phone shows once the site is
// added to its Home Screen. Generated by a few lines of Python (a square,
// a triangle, a box filter; no image library on the machine) and kept here
// as base64 so the worker serves them from memory: no asset binding, and
// the tests can fetch them. Three sizes: 192 and 512 for the manifest
// (Android masks its own shape), 180 for the Apple touch icon (iOS rounds
// the corners itself).
export const ICONS = {
  "icon-192.png": "",
  "icon-512.png": "",
  "apple-touch-icon.png": "",
};

export function iconBytes(name) {
  const b64 = ICONS[name];
  if (!b64) return null;
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}
